-- Sprint 86.3: additive trusted retrieval, review lifecycle, video knowledge, and anonymous quality feedback.
alter table public.knowledge_articles drop constraint if exists knowledge_articles_status_check;
alter table public.knowledge_articles add constraint knowledge_articles_status_check check(status in('draft','review','approved','published','archived'));
alter table public.knowledge_articles add column if not exists knowledge_kind text not null default'knowledge_article'check(knowledge_kind in('knowledge_article','private_article','internal_sop','sales_script','support_playbook','onboarding_checklist','ai_playbook'));
alter table public.knowledge_articles add column if not exists visibility text not null default'workspace'check(visibility in('workspace','organization'));
alter table public.knowledge_articles add column if not exists product_version text;
alter table public.knowledge_articles add column if not exists module text;
alter table public.knowledge_articles add column if not exists feature_key text;
alter table public.knowledge_articles add column if not exists minimum_plan text;
alter table public.knowledge_articles add column if not exists deprecated boolean not null default false;
alter table public.knowledge_articles add column if not exists upcoming boolean not null default false;
alter table public.knowledge_articles add column if not exists approved_by uuid references auth.users(id);
alter table public.knowledge_articles add column if not exists approved_at timestamptz;

create table if not exists public.knowledge_article_relations(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id)on delete cascade,workspace_id uuid not null references public.workspaces(id)on delete cascade,article_id uuid not null references public.knowledge_articles(id)on delete cascade,related_article_id uuid not null references public.knowledge_articles(id)on delete cascade,relation text not null check(relation in('related','supersedes','prerequisite')),created_by uuid references auth.users(id),created_at timestamptz not null default now(),unique(article_id,related_article_id,relation),check(article_id<>related_article_id));
create table if not exists public.knowledge_videos(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id)on delete cascade,workspace_id uuid not null references public.workspaces(id)on delete cascade,title text not null,summary text not null default'',video_url text not null,transcript text not null default'',video_kind text not null check(video_kind in('walkthrough','short_tutorial','feature_introduction','release_highlight')),module text,tags text[]not null default'{}',product_version text,status text not null default'draft'check(status in('draft','review','approved','archived')),created_by uuid references auth.users(id),approved_by uuid references auth.users(id),created_at timestamptz not null default now(),updated_at timestamptz not null default now(),deleted_at timestamptz);
create table if not exists public.knowledge_quality_feedback(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id)on delete cascade,workspace_id uuid not null references public.workspaces(id)on delete cascade,source_reference text not null,rating text not null check(rating in('helpful','not_helpful','needs_update','report_problem')),session_hash text,user_id uuid references auth.users(id),created_at timestamptz not null default now());

create index if not exists knowledge_trusted_retrieval_idx on public.knowledge_articles(organization_id,workspace_id,status,module,product_version,updated_at desc)where deleted_at is null;
create index if not exists knowledge_video_transcript_idx on public.knowledge_videos using gin(to_tsvector('english',title||' '||summary||' '||transcript));
create index if not exists knowledge_quality_feedback_idx on public.knowledge_quality_feedback(organization_id,workspace_id,rating,created_at desc);

alter table public.knowledge_article_relations enable row level security;
alter table public.knowledge_videos enable row level security;
alter table public.knowledge_quality_feedback enable row level security;
create policy "knowledge relations tenant read"on public.knowledge_article_relations for select to authenticated using(public.current_workspace_role(workspace_id)is not null);
create policy "knowledge videos tenant read"on public.knowledge_videos for select to authenticated using(public.current_workspace_role(workspace_id)is not null);
create policy "knowledge quality admin read"on public.knowledge_quality_feedback for select to authenticated using(public.current_workspace_role(workspace_id)in('organization_owner','organization_admin','manager'));

create or replace function public.transition_knowledge_article(p_workspace_id uuid,p_article_id uuid,p_next_status text,p_expected_version integer)returns void language plpgsql security definer set search_path=public as $$declare a public.knowledge_articles%rowtype;v_next text;begin if not public.can_manage_knowledge(p_workspace_id)then raise exception'insufficient knowledge permission';end if;select*into a from public.knowledge_articles where id=p_article_id and workspace_id=p_workspace_id and deleted_at is null for update;if not found or a.version<>p_expected_version then raise exception'knowledge article unavailable or changed';end if;v_next=case a.status when'draft'then'review'when'review'then'approved'when'approved'then'archived'when'published'then'archived'end;if p_next_status is distinct from v_next then raise exception'invalid knowledge transition';end if;insert into public.knowledge_article_versions(article_id,organization_id,workspace_id,version,title,summary,content,tags,created_by)values(a.id,a.organization_id,a.workspace_id,a.version,a.title,a.summary,a.content,a.tags,auth.uid())on conflict do nothing;update public.knowledge_articles set status=p_next_status,version=version+1,approved_by=case when p_next_status='approved'then auth.uid()else approved_by end,approved_at=case when p_next_status='approved'then now()else approved_at end,updated_at=now()where id=a.id;insert into public.organization_audit_events(organization_id,workspace_id,actor_id,event_type,subject_id,metadata)values(a.organization_id,a.workspace_id,auth.uid(),'knowledge.article_transitioned',a.id,jsonb_build_object('from',a.status,'to',p_next_status,'version',a.version+1));end$$;

create or replace function public.retrieve_trusted_knowledge(p_workspace_id uuid,p_query text,p_expanded_terms text[],p_module text default null,p_product_version text default null,p_limit integer default 30)returns table(id uuid,title text,summary text,category text,tags text[],score real,source text,citation text,authority text,version text,module text,video_url text,transcript text,feature_key text,minimum_plan text,deprecated boolean,upcoming boolean)language plpgsql security definer set search_path=public as $$declare v_org uuid;begin select organization_id into v_org from public.workspace_members where workspace_id=p_workspace_id and user_id=auth.uid()and status='active';if v_org is null then raise exception'workspace access required';end if;return query with candidates as(select a.id,a.title,a.summary,a.category,a.tags,(case when a.category in('organization','playbook')or a.knowledge_kind<>'knowledge_article'then 700 when a.category='administrator'then 500 when a.category='release_notes'then 300 when a.category='faq'then 200 else 600 end+case when p_module is not null and(a.module=p_module or p_module=any(a.tags))then 30 else 0 end+case when p_product_version is not null and a.product_version=p_product_version then 20 else 0 end+coalesce((select count(*)*8 from unnest(coalesce(p_expanded_terms,'{}'))t where(a.title||' '||a.summary||' '||a.content||' '||array_to_string(a.tags,' '))ilike'%'||t||'%'),0)-case when a.deprecated then 150 else 0 end)::real s,'article'::text src,a.slug||'@v'||a.version c,case when a.category in('organization','playbook')or a.knowledge_kind<>'knowledge_article'then'organization'when a.category='administrator'then'administrator_guide'when a.category='release_notes'then'release_notes'when a.category='faq'then'faq'else'approved_knowledge_base'end authority,a.version::text,a.module,null::text video_url,null::text transcript,a.feature_key,a.minimum_plan,a.deprecated,a.upcoming from public.knowledge_articles a where a.organization_id=v_org and a.workspace_id=p_workspace_id and a.status in('approved','published')and a.deleted_at is null and a.upcoming=false and exists(select 1 from unnest(coalesce(p_expanded_terms,'{}'))t where(a.title||' '||a.summary||' '||a.content||' '||array_to_string(a.tags,' '))ilike'%'||t||'%') union all select v.id,v.title,v.summary,'video',v.tags,(600+case when p_module is not null and v.module=p_module then 30 else 0 end+coalesce((select count(*)*8 from unnest(coalesce(p_expanded_terms,'{}'))t where(v.title||' '||v.summary||' '||v.transcript)ilike'%'||t||'%'),0))::real,'video',v.id::text||'@'||coalesce(v.product_version,'current'),'approved_knowledge_base',coalesce(v.product_version,'current'),v.module,v.video_url,v.transcript,null,null,false,false from public.knowledge_videos v where v.organization_id=v_org and v.workspace_id=p_workspace_id and v.status='approved'and v.deleted_at is null and exists(select 1 from unnest(coalesce(p_expanded_terms,'{}'))t where(v.title||' '||v.summary||' '||v.transcript)ilike'%'||t||'%'))select c.id,c.title,c.summary,c.category,c.tags,c.s,c.src,c.c,c.authority,c.version,c.module,c.video_url,c.transcript,c.feature_key,c.minimum_plan,c.deprecated,c.upcoming from candidates c order by c.s desc limit least(greatest(p_limit,1),100);end$$;

create or replace function public.record_knowledge_quality_feedback(p_workspace_id uuid,p_article_id text,p_rating text,p_session_id text default null)returns void language plpgsql security definer set search_path=public as $$declare v_org uuid;v_hash text;begin select organization_id into v_org from public.workspace_members where workspace_id=p_workspace_id and user_id=auth.uid()and status='active';if v_org is null then raise exception'workspace access required';end if;if p_rating not in('helpful','not_helpful','needs_update','report_problem')or length(p_article_id)>200 then raise exception'invalid knowledge feedback';end if;v_hash=case when p_session_id is null or p_session_id=''then null else encode(extensions.digest(left(p_session_id,200),'sha256'),'hex')end;insert into public.knowledge_quality_feedback(organization_id,workspace_id,source_reference,rating,session_hash,user_id)values(v_org,p_workspace_id,p_article_id,p_rating,v_hash,null);insert into public.organization_audit_events(organization_id,workspace_id,actor_id,event_type,metadata)values(v_org,p_workspace_id,auth.uid(),'knowledge.feedback_recorded',jsonb_build_object('rating',p_rating,'source_reference',left(p_article_id,200)));end$$;

revoke all on function public.transition_knowledge_article(uuid,uuid,text,integer),public.retrieve_trusted_knowledge(uuid,text,text[],text,text,integer),public.record_knowledge_quality_feedback(uuid,text,text,text)from public;
grant execute on function public.transition_knowledge_article(uuid,uuid,text,integer),public.retrieve_trusted_knowledge(uuid,text,text[],text,text,integer),public.record_knowledge_quality_feedback(uuid,text,text,text)to authenticated;
